<?php

namespace App\Models;

use App\Enums\VideoLanguage;
use App\Models\Concerns\BelongsToOrganization;
use Database\Factories\TranscriptSegmentFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Attributes\Hidden;
use Illuminate\Database\Eloquent\Attributes\Scope;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One timed piece of a Whisper transcript. search_vector is generated by PostgreSQL.
 */
#[Fillable(['organization_id', 'video_id', 'start_ms', 'end_ms', 'text', 'search_config'])]
#[Hidden(['search_vector'])]
class TranscriptSegment extends Model
{
    /** @use HasFactory<TranscriptSegmentFactory> */
    use BelongsToOrganization, HasFactory;

    public function video(): BelongsTo
    {
        return $this->belongsTo(Video::class);
    }

    /**
     * Full-text search in French and English, accent-insensitive.
     * The configurations are constants so that PostgreSQL can use the GIN index.
     */
    #[Scope]
    protected function search(Builder $query, string $terms): void
    {
        $tsqueries = collect(VideoLanguage::cases())
            ->map(fn (VideoLanguage $language) => "websearch_to_tsquery('{$language->searchConfig()}', ?)")
            ->implode(' || ');

        $query->whereRaw(
            "search_vector @@ ({$tsqueries})",
            array_fill(0, count(VideoLanguage::cases()), $terms),
        );
    }

    protected function casts(): array
    {
        return [
            'start_ms' => 'integer',
            'end_ms' => 'integer',
        ];
    }
}
